BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-20128'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='4T0953' OR source_url ~ '[?&]id=20128(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='dbc20953-5a21-46bc-aae5-941268820128' OR slug='sam-sarika-nakhon-nayok-land-three-groups-4t0953' OR (abs(latitude-14.28784)<0.0001 AND abs(longitude-101.27852)<0.0001 AND abs(land_area_sqm-265357.2)<1)) THEN RAISE NOTICE 'SAM 4T0953 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('dbc20953-5a21-46bc-aae5-941268820128', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'land', 'business', 'sale', 'whole_property', 'ที่ดินสาริกา นครนายก 10 แปลง 3 กลุ่ม รวม 165 ไร่ 3 งาน 39.3 ตร.ว.', 'รายละเอียดทรัพย์

ที่ดินตำบลสาริกา อำเภอเมืองนครนายก จังหวัดนครนายก บริเวณถนนนครนายก–นางรอง (ทล.3049) และถนนทางเข้าน้ำตกสาริกา (ทล.3050) รวม 10 แปลง เนื้อที่ 165 ไร่ 3 งาน 39.3 ตร.ว. หรือ 66,339.3 ตร.ว. (265,357.2 ตร.ม.) ราคาประกาศขาย SAM 187,909,000 บาท รหัส 4T0953 ต้นทางแสดงราคาประมาณ 2,833 บาท/ตร.ว. ใช้ราคารวมเป็นหลัก

เอกสารสิทธิ์มีโฉนดตราจองเลขที่ 120 จำนวน 1 ฉบับ และโฉนดที่ดินเลขที่ 9597, 9598, 10206, 10394, 10395, 10404, 13239, 13240 และ 16669 จำนวน 9 ฉบับ รวม 10 ฉบับ ไม่ใช่โฉนดที่ดินประเภทเดียวกันทั้งหมด

การแบ่งกลุ่มที่ดิน

กลุ่มที่ 1: 6 แปลง รวม 92 ไร่ 3 งาน 58 ตร.ว. ด้านใต้ติดถนน ทล.3049 กว้างประมาณ 124 เมตร ลึกสุดประมาณ 880 เมตร ด้านตะวันตกติดคลองเรือและคลองสาริกาประมาณ 810 เมตร ระดับที่ดินสูงต่ำตามภูมิประเทศ SAM ระบุมีสาธารณูปโภคพื้นฐานครบ ถนนสาธารณะลาดยาง 4 ช่องจราจร พร้อมไหล่ทางและช่องจักรยาน 1 ช่อง กว้างประมาณ 18–20 เมตร

กลุ่มที่ 2: 2 แปลง รวม 8 ไร่ 84 ตร.ว. ด้านตะวันตกติดถนนทางเข้าน้ำตกสาริกา ทล.3050 กว้างประมาณ 240 เมตร ลึกสุดประมาณ 48 เมตร ด้านเหนือและตะวันออกติดคลองสาริกา ระดับที่ดินสูงต่ำตามภูมิประเทศ SAM ระบุมีสาธารณูปโภคพื้นฐานครบ ถนนสาธารณะลาดยาง 2 ช่องจราจรพร้อมไหล่ทาง กว้างประมาณ 10 เมตร

กลุ่มที่ 3: 2 แปลง รวม 64 ไร่ 2 งาน 97.3 ตร.ว. ไม่มีพื้นที่ติดถนน มีคลองเรือและคลองสาริกาคั่นจากกลุ่มที่ 1 และ 2 และ SAM ระบุว่ายังไม่มีสะพานข้าม ด้านเหนือติดคลองเรือประมาณ 320 เมตร ด้านใต้ประมาณ 110 เมตร ด้านตะวันออกประมาณ 710 เมตร ด้านตะวันตกติดคลองและแปลงข้างเคียงประมาณ 645 เมตร ระดับที่ดินสูงต่ำตามภูมิประเทศ อยู่ห่างจุดสาธารณูปโภคประมาณ 100 เมตร

ข้อควรทราบเกี่ยวกับการเข้าถึง

ที่ดินอยู่ใกล้กันแต่ไม่ได้ต่อเนื่องเป็นผืนเดียวทั้งหมด การมีหน้าถนนและสาธารณูปโภคของกลุ่มที่ 1 และ 2 ไม่ได้หมายความว่ากลุ่มที่ 3 เข้าถึงได้แบบเดียวกัน ควรตรวจสิทธิและวิธีเข้าถึงกลุ่มที่ 3 รวมถึงเงื่อนไขที่เกี่ยวข้องหากจะทำทางข้ามคลองกับหน่วยงานที่รับผิดชอบก่อนเสนอซื้อ ไม่ถือว่ามีสิทธิสร้างสะพานหรือทางข้ามได้โดยอัตโนมัติ

ทำเลและการเดินทาง

SAM ระบุผังเมืองสีเขียว อยู่ในย่านเกษตรกรรมและแหล่งท่องเที่ยว ใกล้น้ำตกสาริกา น้ำตกวังตะไคร้ เขื่อนขุนด่านปราการชลและที่ทำการ อบต.สาริกา จากน้ำตกนางรองมุ่งหน้าน้ำตกสาริกาบนถนน ทล.3049 ผ่านวัดสวนหงษ์ ถึงประมาณ กม.11+500 ทรัพย์อยู่ขวามือ ควรตรวจข้อกำหนดการใช้ประโยชน์ให้ตรงกับแผนงานของผู้ซื้อ

ภาพและข้อมูลต้นทาง

ภาพจริงและผังจาก SAM รวม 15 ภาพ มีภาพลงวันที่ 5 เมษายน 2565 และ 30 พฤษภาคม 2565 ควรตรวจสภาพปัจจุบัน พิกัด 14.287840, 101.278520 ดึงจากลิงก์นำทาง SAM และตรงกับลิงก์แผนที่ เป็นจุดอ้างอิงของชุดทรัพย์ ไม่ใช่แนวเขตแต่ละกลุ่ม

ราคาและสถานะซื้อตรงตรวจจากหน้า SAM วันที่ 15 กันยายน 2569 ติดต่อ SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 4T0953 เพื่อยืนยันราคา สถานะพร้อมขาย การนัดชม เอกสารสิทธิ์และเงื่อนไขล่าสุด', 187909000, false, 265357.2, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'บริเวณถนนนครนายก–นางรอง ทล.3049 กม.11+500', 'ที่ดิน 3 กลุ่มใกล้ทางเข้าน้ำตกสาริกา ทล.3050', 'ถนนนครนายก–นางรอง (ทล.3049)', 14.28784, 101.27852, 'นครนายก', 'เมืองนครนายก', 'สาริกา', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-sarika-nakhon-nayok-land-three-groups-4t0953') RETURNING id INTO property_listing_id;
